def search_automation(output: Path, question: str, limit: int = 8) -> list[dict[str, Any]]:
    path = output.resolve() / AUTOMATION_DATABASE
    if not path.is_file():
        return []
    terms = [value for value in re.findall(r"[\w\u3400-\u9fff.-]+", question.casefold()) if len(value) >= 2][:16]
    if not terms:
        return []
    query = " OR ".join('"' + value.replace('"', '""') + '"' for value in terms)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = [
            dict(row)
            for row in connection.execute(
                "SELECT p.review_id,p.title,p.kind,p.status,p.human_file,p.content,p.changed_paths_json,"
                "bm25(automation_fts,0.0,6.0,3.0,2.0) AS rank "
                "FROM automation_fts JOIN pending_reviews p USING(review_id) WHERE automation_fts MATCH ? ORDER BY rank, p.review_id LIMIT ?",
                (query, limit),
            )
        ]
    except sqlite3.OperationalError:
        rows = []
    finally:
        connection.close()
    for row in rows:
        row["changed_paths"] = json.loads(row.pop("changed_paths_json"))
    return rows

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def background_process_options(*, visible: bool = False) -> dict[str, Any]:
    """Hide non-interactive Windows child consoles without changing I/O semantics."""
    if visible or os.name != "nt":
        return {}
    creation_flag = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return {"creationflags": creation_flag} if creation_flag else {}

def command_version(executable: str, args: Iterable[str] = ("--version",)) -> dict[str, Any]:
    resolved = shutil.which(executable)
    if not resolved:
        return {"status": "missing", "command": executable, "path": None, "version": None}
    completed = run([resolved, *args], timeout=20)
    text = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "status": "ready" if completed.returncode == 0 else "broken",
        "command": executable,
        "path": str(Path(resolved).resolve()),
        "version": text[0] if text else None,
        "exit_status": completed.returncode,
    }

def clear_markers(output: Path) -> None:
    for name in (
        ".pending-agent-review",
        ".failed",
        ".complete",
        ".machine.complete",
        ".human.complete",
    ):
        (output / name).unlink(missing_ok=True)

def write_marker(output: Path, name: str, payload: dict[str, Any]) -> None:
    clear_markers(output)
    json_write(output / name, payload)

def safe_title(text: str, limit: int = 120) -> str:
    value = re.sub(r"[\\/:*?\"<>|\[\]]+", "-", text).strip(" .-")
    return (value[:limit] or "untitled").strip()

def path_inside(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False

def safe_rmtree(path: Path, root: Path) -> None:
    """Remove one verified descendant without ever accepting the root itself."""
    resolved_path = path.resolve()
    resolved_root = root.resolve()
    if resolved_path == resolved_root or not path_inside(resolved_path, resolved_root):
        raise CkbError(f"recursive removal target is outside its declared root: {resolved_path}")
    if resolved_path.exists():
        shutil.rmtree(resolved_path)

def prepare_feedback_store(output: Path) -> dict[str, Any]:
    """Create only the feedback-owned directories for a finalized Markdown KB."""
    output = output.resolve()
    metadata = output / "workspace-meta/feedback"
    for status in STATUS_DIRECTORY.values():
        (metadata / status).mkdir(parents=True, exist_ok=True)
    vaults = []
    for name in ("markdown", "human"):
        root = output / name
        if root.is_dir():
            for relative in FEEDBACK_DIRECTORIES:
                (root / relative).mkdir(parents=True, exist_ok=True)
            vaults.append(str(root.resolve()))
    return {
        "schema_version": FEEDBACK_SCHEMA_VERSION,
        "status": "ready",
        "metadata_root": str(metadata.resolve()),
        "vaults": vaults,
    }

def _canonical_relative_target(output: Path, target: Path) -> tuple[str, Path, Path]:
    output = output.resolve()
    human = output / "human"
    markdown = output / "markdown"
    if not human.is_dir() or not markdown.is_dir():
        raise CkbError("feedback requires finalized human and markdown knowledge roots")
    raw = str(target).replace("\\", "/")
    candidate = Path(target)
    if candidate.is_absolute():
        resolved = candidate.resolve()
        if path_inside(resolved, human):
            relative = resolved.relative_to(human).as_posix()
        elif path_inside(resolved, markdown):
            relative = resolved.relative_to(markdown).as_posix()
        else:
            raise CkbError("feedback target must be inside OUTPUT/human or OUTPUT/markdown")
    else:
        for prefix in ("human/", "markdown/"):
            if raw.startswith(prefix):
                raw = raw[len(prefix) :]
                break
        pure = PurePosixPath(raw)
        if pure.is_absolute() or ".." in pure.parts:
            raise CkbError("feedback target must be a knowledge-root relative path")
        relative = pure.as_posix().lstrip("./")
    if not relative or relative.startswith("feedback/") or not relative.endswith(".md"):
        raise CkbError("feedback target must be a non-feedback Markdown knowledge page")
    human_target = human / relative
    markdown_target = markdown / relative
    if not human_target.is_file() or not markdown_target.is_file():
        raise CkbError(f"feedback target is missing from the mirrored human knowledge roots: {relative}")
    if human_target.read_bytes() != markdown_target.read_bytes():
        raise CkbError(f"feedback target differs between human and markdown roots: {relative}")
    return relative, human_target, markdown_target

def _read_chinese_body(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} body does not exist: {path}")
    value = path.read_text(encoding="utf-8-sig").strip()
    if not value:
        raise CkbError(f"{label} body must not be empty")
    if not _contains_chinese(value):
        raise CkbError(f"{label} narrative must use Simplified Chinese")
    if value.startswith("---\n") or LONG_HEX.search(value):
        raise CkbError(f"{label} body must omit frontmatter and hash-like identifiers")
    return value

def _line_selection(text: str, start_line: int, end_line: int) -> tuple[str, str, str]:
    if start_line < 1 or end_line < start_line:
        raise CkbError("feedback line range must be a positive inclusive range")
    lines = text.splitlines(keepends=True)
    if end_line > len(lines):
        raise CkbError(f"feedback line range exceeds target length: {end_line}>{len(lines)}")
    start_offset = sum(len(value) for value in lines[: start_line - 1])
    end_offset = sum(len(value) for value in lines[:end_line])
    anchor_text = text[start_offset:end_offset]
    if not anchor_text:
        raise CkbError("feedback selection must not be empty")
    return text[max(0, start_offset - 80) : start_offset], anchor_text, text[end_offset : end_offset + 80]

def _next_feedback_id(output: Path) -> str:
    prefix = dt.datetime.now(dt.timezone.utc).strftime("feedback-%Y%m%d-%H%M%S")
    existing = {
        path.stem
        for status in STATUS_DIRECTORY.values()
        for path in (output / "workspace-meta/feedback" / status).glob(f"{prefix}-*.json")
    }
    index = 1
    while f"{prefix}-{index:02d}" in existing:
        index += 1
    return f"{prefix}-{index:02d}"

def _blockquote(value: str) -> str:
    lines = value.rstrip("\n").splitlines() or [""]
    return "\n".join("> " + line for line in lines)

def _load_feedback(output: Path, feedback_id: str) -> tuple[dict[str, Any], Path]:
    if not re.fullmatch(r"feedback-\d{8}-\d{6}-\d{2,}", feedback_id):
        raise CkbError("feedback identifier has an invalid shape")
    matches = [path for status in STATUS_DIRECTORY for path in [_record_path(output, status, feedback_id)] if path.is_file()]
    if len(matches) != 1:
        raise CkbError(f"feedback identifier must resolve to exactly one record: {feedback_id}")
    return json_load(matches[0]), matches[0]

def _all_offsets(text: str, needle: str) -> list[int]:
    offsets = []
    start = 0
    while needle:
        value = text.find(needle, start)
        if value < 0:
            break
        offsets.append(value)
        start = value + 1
    return offsets

def _locate_anchor(text: str, record: dict[str, Any]) -> dict[str, Any]:
    start_line, end_line = [int(value) for value in record["target_lines"]]
    lines = text.splitlines(keepends=True)
    if 1 <= start_line <= end_line <= len(lines):
        start = sum(len(value) for value in lines[: start_line - 1])
        end = sum(len(value) for value in lines[:end_line])
        if record["anchor_text"] in text[start:end]:
            return {"status": "line-range", "current_lines": [start_line, end_line], "match_count": 1}
    offsets = _all_offsets(text, str(record["anchor_text"]))
    if len(offsets) == 1:
        start = offsets[0]
        return {
            "status": "unique-text",
            "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
            "match_count": 1,
        }
    if len(offsets) > 1:
        window = str(record["anchor_before"]) + str(record["anchor_text"]) + str(record["anchor_after"])
        windows = _all_offsets(text, window)
        if len(windows) == 1:
            start = windows[0] + len(record["anchor_before"])
            return {
                "status": "anchor-window",
                "current_lines": _offset_lines(text, start, start + len(record["anchor_text"])),
                "match_count": len(offsets),
            }
    return {"status": "stale", "current_lines": None, "match_count": len(offsets)}

def _canonical_applied_record(output: Path, path: Path | None) -> str | None:
    if path is None:
        return None
    resolved = path.resolve()
    if not resolved.is_file() or not path_inside(resolved, output.resolve()):
        raise CkbError("applied record must be an existing file inside the knowledge output")
    relative = resolved.relative_to(output.resolve())
    if len(relative.parts) < 3 or relative.parts[0] not in {"human", "markdown"}:
        raise CkbError("applied record must point to a reviewed human knowledge note")
    note_directories = {"analysis", "changes", "pitfalls", "experiments", "sessions"}
    if relative.parts[1] not in note_directories or resolved.suffix.casefold() != ".md":
        raise CkbError("applied record must point to an analysis, change, pitfall, experiment, or session note")
    note_relative = Path(*relative.parts[1:])
    human = output / "human" / note_relative
    markdown = output / "markdown" / note_relative
    if not human.is_file() or not markdown.is_file() or human.read_bytes() != markdown.read_bytes():
        raise CkbError("applied record must have byte-identical human and markdown note mirrors")
    title = _title_of(human)
    metadata = output / "workspace-meta/notes" / f"{safe_title(title)}.json"
    if not metadata.is_file():
        raise CkbError("applied record metadata is missing; create the note through record")
    value = json_load(metadata)
    if value.get("status") != "agent-reviewed" or value.get("title") != title:
        raise CkbError("applied record must have agent-reviewed metadata")
    return relative.as_posix()

def _query_terms(question: str) -> list[str]:
    terms = {value.casefold() for value in re.findall(r"[A-Za-z0-9_.:#/-]{2,}", question)}
    for run in re.findall(r"[\u3400-\u9fff]+", question):
        terms.add(run)
        terms.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(terms, key=lambda value: (-len(value), value))

def _root(output: Path) -> Path:
    value = output.resolve() / "workspace-meta" / "freshness"
    for relative in ("overlays", "plans"):
        (value / relative).mkdir(parents=True, exist_ok=True)
    return value

def _pid_alive(pid: Any) -> bool:
    try:
        value = int(pid)
    except (TypeError, ValueError):
        return False
    if value <= 0:
        return False
    if value == os.getpid():
        return True
    if os.name == "nt":
        import ctypes

        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, value)
        if handle:
            ctypes.windll.kernel32.CloseHandle(handle)
            return True
        return False
    try:
        os.kill(value, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False

def _read_lock(path: Path) -> dict[str, Any]:
    try:
        value = json_load(path)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}

def _lock_file_identity(path: Path) -> tuple[int, int] | None:
    try:
        metadata = path.stat()
    except OSError:
        return None
    return int(metadata.st_dev), int(metadata.st_ino)

def _release_owned_state_lock(
    lock_path: Path,
    owner_token: str,
    acquired_identity: tuple[int, int] | None,
    timeout: float,
) -> None:
    """Release only this owner while tolerating short Windows sharing conflicts."""

    deadline = time.monotonic() + max(0.0, timeout)
    last_error = "lock-remained-busy"
    while True:
        try:
            current = json_load(lock_path)
        except FileNotFoundError:
            return
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            last_error = f"read:{type(exc).__name__}:{str(exc)[:160]}"
        else:
            current_identity = _lock_file_identity(lock_path)
            if current.get("owner_token") != owner_token:
                return
            if acquired_identity is not None and current_identity != acquired_identity:
                return
            try:
                # Reopen immediately before deletion so every retry observes
                # the latest owner instead of acting on an earlier sample.
                confirmed = json_load(lock_path)
                confirmed_identity = _lock_file_identity(lock_path)
                if confirmed.get("owner_token") != owner_token:
                    return
                if acquired_identity is not None and confirmed_identity != acquired_identity:
                    return
                lock_path.unlink()
                return
            except FileNotFoundError:
                return
            except (PermissionError, OSError) as exc:
                last_error = f"unlink:{type(exc).__name__}:{str(exc)[:160]}"
        if time.monotonic() >= deadline:
            raise CkbError(
                "fact freshness state lock release timeout: "
                f"path={lock_path}; owner_token={owner_token}; last_error={last_error}"
            )
        time.sleep(LOCK_RETRY_SECONDS)

def _bounded_text(value: Any, field: str, limit: int = 2000) -> str:
    text = str(value or "").strip()
    if not text or len(text) > limit or any(character in text for character in ("\x00", "\r", "\n")):
        raise CkbError(f"fact freshness {field} must be bounded nonempty single-line text")
    return text

def _repository_binding(output: Path, repository: Path | None) -> tuple[Path, dict[str, Any], str]:
    state_path = output.resolve() / "state.json"
    if not state_path.is_file():
        raise CkbError(f"fact freshness requires knowledge state.json: {state_path}")
    state = json_load(state_path)
    if not isinstance(state, dict) or state.get("status") != "complete":
        raise CkbError("fact freshness requires a complete knowledge output state")
    binding = state.get("repository")
    if not isinstance(binding, dict):
        raise CkbError("fact freshness knowledge state has no repository binding")
    bound_commit = str(binding.get("commit") or "").strip()
    if not _HEX_OBJECT.fullmatch(bound_commit):
        raise CkbError("fact freshness knowledge state has no valid bound commit")
    configured_root = str(binding.get("root") or "").strip()
    repo = (repository or (Path(configured_root) if configured_root else None))
    if repo is None:
        raise CkbError("fact freshness repository root is unavailable")
    repo = repo.expanduser().resolve()
    if not repo.is_dir():
        raise CkbError(f"fact freshness repository root is missing: {repo}")
    return repo, state, bound_commit

def _git(repo: Path, *arguments: str, allow_failure: bool = False) -> str | None:
    completed = run(["git", "-C", str(repo), *arguments], timeout=GIT_TIMEOUT_SECONDS)
    if completed.returncode:
        if allow_failure:
            return None
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness Git probe failed: git -C {repo} {' '.join(arguments)}: {detail[:500]}")
    return completed.stdout.strip()

def _status_records(repo: Path) -> list[dict[str, str]]:
    completed = run(
        ["git", "-C", str(repo), "status", "--porcelain=v1", "-z", "--untracked-files=all"],
        timeout=GIT_TIMEOUT_SECONDS,
    )
    if completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness Git status failed: {detail[:500]}")
    frames = completed.stdout.split("\0")
    records: list[dict[str, str]] = []
    index = 0
    while index < len(frames):
        frame = frames[index]
        index += 1
        if len(frame) < 3:
            continue
        status = frame[:2]
        path = frame[3:].replace("\\", "/")
        if path:
            records.append({"status": status, "path": path})
        if any(marker in status for marker in ("R", "C")) and index < len(frames):
            index += 1
    return sorted(records, key=lambda item: (item["path"], item["status"]))

def _change_summary(repo: Path, bound_commit: str, current_head: str) -> dict[str, Any]:
    if bound_commit == current_head:
        return {
            "comparison": "bound-commit-to-current-head",
            "changed": 0,
            "changed_paths": [],
            "counts": {},
            "truncated": False,
        }
    if _git(repo, "cat-file", "-e", f"{bound_commit}^{{commit}}", allow_failure=True) is None:
        raise CkbError(f"fact freshness bound commit object is unavailable: {bound_commit}")
    completed = run(
        ["git", "-C", str(repo), "diff", "--name-status", "--find-renames", bound_commit, current_head],
        timeout=GIT_TIMEOUT_SECONDS,
    )
    if completed.returncode:
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"fact freshness committed range diff failed: {detail[:500]}")
    changes: list[dict[str, Any]] = []
    counts: dict[str, int] = {}
    for line in completed.stdout.splitlines():
        fields = line.split("\t")
        if len(fields) < 2:
            continue
        raw_status = fields[0]
        kind = raw_status[:1] or "?"
        counts[kind] = counts.get(kind, 0) + 1
        changes.append(
            {
                "status": raw_status,
                "path": fields[-1].replace("\\", "/"),
                **({"from_path": fields[1].replace("\\", "/")} if len(fields) > 2 else {}),
            }
        )
    return {
        "comparison": "bound-commit-to-current-head",
        "changed": len(changes),
        "changed_paths": [item["path"] for item in changes[:MAX_CHANGED_PATHS]],
        "changes": changes[:MAX_CHANGED_PATHS],
        "counts": dict(sorted(counts.items())),
        "truncated": len(changes) > MAX_CHANGED_PATHS,
    }

def _prune_overlays(root: Path) -> None:
    paths = sorted((root / "overlays").glob("*.json"), key=lambda item: item.stat().st_mtime, reverse=True)
    now = time.time()
    for index, path in enumerate(paths):
        try:
            record = json_load(path)
            expired = float(record.get("lifetime", {}).get("expires_unix") or 0) <= now
        except Exception:
            expired = True
        if expired or index >= MAX_OVERLAYS:
            path.unlink(missing_ok=True)
